    ('FxDigitalBarrierOption:GarmanKohlhagen:FdBlackScholesBarrierEngine', ores_utility_system_tenant_id_fn(), 0, 'GarmanKohlhagen', 'FdBlackScholesBarrierEngine', 'FxDigitalBarrierOption', true, 'Builds a FdBlackScholesBarrierEngine.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('FormulaBasedCoupon:BrigoMercurio:MC', ores_utility_system_tenant_id_fn(), 0, 'BrigoMercurio', 'MC', 'FormulaBasedCoupon', true, 'Builds a MCGaussianFormulaBasedCouponPricer. We refer to the formula based coupon module documentation for further details.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('RateDigitalOption:Black:CallSpreadEngine', ores_utility_system_tenant_id_fn(), 0, 'Black', 'CallSpreadEngine', 'RateDigitalOption', true, 'Builds a RateDigitalCallSpreadEngine that prices a European cash-or-nothing digital option on an interest rate fixing via call-spread replication. For a digital call paying P if the fixing L > K: textPV = P times fracC(K - varepsilon/2,, sigma_-) - C(K + varepsilon/2,, sigma_+)varepsilon where C(K, sigma) is the vanilla caplet/floorlet price at strike K using the market optionlet volatility sigma(K) from the cap/floor volatility surface. The formula for a digital put is analogous using put prices. Both Black (shifted-lognormal) and Bachelier (normal) volatility types are supported automatically depending on the optionlet surface type.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('FxForward:DiscountedCashflows:DiscountingFxForwardEngine', ores_utility_system_tenant_id_fn(), 0, 'DiscountedCashflows', 'DiscountingFxForwardEngine', 'FxForward', true, 'Builds a DiscountingFxForwardEngine.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('FxForward:CrossAssetModel:AMC', ores_utility_system_tenant_id_fn(), 0, 'CrossAssetModel', 'AMC', 'FxForward', false, 'Builds a McCamFxForwardEngine for use in AMC simulations. We refer to the AMC module documentation for further details. Parameter IncludeSettlementDateFlows is set to false by default, i.e. cash flows on the maturity date of the trade are not taken into account when pricing as of maturity date so that the trade has zero value on maturity. In case of true we do take the final flows into account while the trade is "maturing".', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('FxOption:GarmanKohlhagen:AnalyticEuropeanEngine', ores_utility_system_tenant_id_fn(), 0, 'GarmanKohlhagen', 'AnalyticEuropeanEngine', 'FxOption', true, 'Builds a AnalyticEuropeanEngine.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('FxOption:CrossAssetModel:AMC', ores_utility_system_tenant_id_fn(), 0, 'CrossAssetModel', 'AMC', 'FxOption', false, 'Builds a McCamFxOptionEngine for use in AMC simulations. We refer to the AMC module documentation for further details.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('FxOptionEuropeanCS:GarmanKohlhagen:AnalyticCashSettledEuropeanEngine', ores_utility_system_tenant_id_fn(), 0, 'GarmanKohlhagen', 'AnalyticCashSettledEuropeanEngine', 'FxOptionEuropeanCS', true, 'Builds a AnalyticCashSettledEuropeanEngine.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
