    ('Swap:DiscountedCashflows:DiscountingSwapEngine', ores_utility_system_tenant_id_fn(), 0, 'DiscountedCashflows', 'DiscountingSwapEngine', 'Swap', true, 'Builds a DiscountingSwapEngine.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('Swap:CrossAssetModel:AMC', ores_utility_system_tenant_id_fn(), 0, 'CrossAssetModel', 'AMC', 'Swap', false, 'Builds a McLgmSwapEngine for use in AMC simulations. We refer to the AMC module documentation for further details.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('CrossCurrencySwap:DiscountedCashflows:DiscountingCrossCurrencySwapEngine', ores_utility_system_tenant_id_fn(), 0, 'DiscountedCashflows', 'DiscountingCrossCurrencySwapEngine', 'CrossCurrencySwap', true, 'Builds a DiscountingCurrencySwapEngine.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('CrossCurrencySwap:CrossAssetModel:AMC', ores_utility_system_tenant_id_fn(), 0, 'CrossAssetModel', 'AMC', 'CrossCurrencySwap', false, 'Builds a McCamCurrencySwapEngine for use in AMC simulations. We refer to the AMC module documentation for further details.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('RiskParticipationAgreement_Vanilla:Black:Analytic', ores_utility_system_tenant_id_fn(), 0, 'Black', 'Analytic', 'RiskParticipationAgreement_Vanilla', true, 'Builds a AnalyticBlackRiskParticipationAgreementEngine.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('RiskParticipationAgreement_Vanilla_XCcy:Black:Analytic', ores_utility_system_tenant_id_fn(), 0, 'Black', 'Analytic', 'RiskParticipationAgreement_Vanilla_XCcy', true, 'Builds a AnalyticXCcyBlackRiskParticipationAgreementEngine.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('RiskParticipationAgreement_Structured:LGM:Grid', ores_utility_system_tenant_id_fn(), 0, 'LGM', 'Grid', 'RiskParticipationAgreement_Structured', true, 'Builds a NumericLgmRiskParticipationAgreementEngine.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('RiskParticipationAgreement_TLock:LGM:Grid', ores_utility_system_tenant_id_fn(), 0, 'LGM', 'Grid', 'RiskParticipationAgreement_TLock', true, 'Builds a NumericLgmRiskParticipationAgreementEngine.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('ScriptedTrade:ScriptedTrade:ScriptedTrade', ores_utility_system_tenant_id_fn(), 0, 'ScriptedTrade', 'ScriptedTrade', 'ScriptedTrade', true, 'Builds a ScriptedInstrumentPricingEngine (and variants). We refer to the scripted trade module documentation for a sample configuration and more details. subsectionGlobal Parameters In addition to product specific settings there is also a block with global parameters with the following meaning: beginitemize item ContinueOnCalibrationError: If set to true an exceedence of a prescribed model calibration tolerance (for e.g. the LGM model) will not cause the trade building to fail, instead a warning is logged and the trade is processed anyway. Optional, defaults to false. item AllowModelFallbacks: If set to true a missing market object during the build of a model will not cause the build to fail. Instead, a fallback will be used. For example, if a volatility surface is missing during the build of the LGM or CAM model, a zero volatility surface might be used as a fallback and the calculation continues. Optional, defaults to false. item Calibrate: If false, model calibration is disabled. This flag is usually not present in a user configuration, but only used internally for certain workflows within ORE which do not require a model calibration. Optional, defaults to true. item GenerateAdditionalResults: If false, the generation of additional results within pricing engines will be suppressed (for those pricing engines which support this). This flag is usually not present in a user configuration, but only used internally to improve the performance for processes which only rely on the NPV as a result from pricing engines, e.g. when repricing trades under sensitivity or stress scenarios. Optional, defaults to false. item RunType: Set automatically. One of NPV, SensitivityDelta, SensitivityDeltaGamma, Stress, Exposure, Capital, TradeDetails, PortfolioAnalyser, HistoricalPnL, BondSpreadImply, AbsMaturityUpdate depending on the context for which a portfolio was built. Might also be left empty. This is used by some pricing engines to adapt to certain run types. E.g. a first order sensitivity pnl expansion might be used for a SensitivityDelta run by an engine which is able to compute analytical or AAD first order sensitivities. item McType: Set automatically. One of Classic and American depending on the context for which the pricinge engines file is referenced. Might also be left empty. This is used by some trade constructions to adapt to certain monte carlo types. E.g. Pricer would not be attached to coupons which can be computed in AMC without a leg / coupon pricer item StrikeSpread: Defaults to 0.1. If set, overrides the default value used to calculate the strike spread for replication engines. item BondFutureAmericanAsEuropean: This parameter can be set to true or false or to a regex inclusion pattern. If set to false, the default, there is no effect. If set to true, all bond future option trades with American exercise are priced as if they had European exercise i.e. with a European bond future option engine. If set to a regex pattern, all bond future option trades where the underlying contract name matches the regex will be priced as if they had European exercise. Bond future option trades where the underlying contract name does not match the regex will not be impacted i.e. if they have American exercise, they will be priced as such. enditemize.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary')
on conflict (tenant_id, code)
where valid_to = ores_utility_infinity_timestamp_fn()
do nothing;

select 'Pricing Model Engine Pairs' as entity, count(*) as count
from ores_analytics_pricing_model_engine_pairs_tbl
where valid_to = ores_utility_infinity_timestamp_fn();
